const express = require('express');
const session = require('express-session');
const MongoStore = require('connect-mongo');

const app = express();

const mongoStore = MongoStore.create({
  mongoUrl: process.env.MONGO_URI,
  collectionName: 'sessions'
});

app.use(session({
  store: mongoStore,
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false
}));

app.delete('/api/workspaces/:workspaceId/force-logout', async (req, res) => {
  if (!req.session || !req.session.userId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Validate that user is administrator of the targeted workspace
  if (req.session.workspaceId !== req.params.workspaceId || req.session.role !== 'WORKSPACE_ADMIN') {
    return res.status(403).json({ error: 'Access denied: you must be an administrator of this workspace' });
  }

  try {
    const result = await mongoStore.collection.deleteMany({
      'session.workspaceId': req.params.workspaceId
    });

    res.json({
      success: true,
      revokedCount: result.deletedCount
    });
  } catch (err) {
    res.status(500).json({ error: 'Mass logout operation failed' });
  }
});

app.listen(4044);
